  an: true,
  the: true,
  of: true,
  some: true,
  my: true,
  your: true,
  his: true,
  her: true,
  their: true,
  our: true,
  this: true,
  that: true,
  these: true,
  those: true,
  and: true,
  or: true,
  for: true,
  to: true,
  from: true,
  at: true,
  with: true,
  in: true,
  on: true,
  by: true,
  per: true,
  as: true,
