  places: {
    wend_vale: {
      id: "wend_vale",
      name: "Wend Vale",
      fields: {
        description: "A broad green valley where the River Wend slows and spreads. Orchards and mill-ponds crowd the near bank; woods and grazing climb the far one.",
        tags: ["region"],
        region: "region_wend_vale"
      },
      sceneType: "exploration"
    },
    brindlemere: {
      id: "brindlemere",
      name: "Brindlemere",
      fields: {
        description: "A market town of grey stone and red tile, about eight hundred souls, built where the high road meets the ferry. Everything in it is a short walk from the square.",
        tags: ["town"]
      },
      parent: "wend_vale",
      sceneType: "exploration"
    },
    market_square: {
      id: "market_square",
      name: "Market Square",
      fields: {
        description: "A cobbled square with a stone well at its heart. On Marketday the stalls go up before dawn and the whole vale comes to trade.",
        tags: ["square"]
      },
      parent: "brindlemere",
      sceneType: "market",
      grid: "market_square_grid"
    },
    crooked_kettle: {
      id: "crooked_kettle",
      name: "The Crooked Kettle",
      fields: {
        description: "A leaning, low-beamed inn with a copper kettle hung crooked over the door. Warm, noisy and always smelling of onions and woodsmoke; there are six beds upstairs and a stable yard behind.",
        tags: ["inn"]
      },
      parent: "market_square",
      sceneType: "conversation",
      cell: { x: 2, y: 1 }
    },
    reeves_hall: {
      id: "reeves_hall",
      name: "Reeve's Hall",
      fields: {
        description: "The town's broad-windowed meeting hall. The reeve keeps his ledgers here, petitioners queue in the passage, and the framed Charter hangs behind the long table.",
        tags: ["civic"]
      },
      parent: "market_square",
      sceneType: "conversation",
      cell: { x: 6, y: 1 }
    },
    wren_cottage: {
      id: "wren_cottage",
      name: "Wren's Cottage",
      fields: {
        description: "A narrow cottage hung with drying bundles of yarrow, mint and willow bark. A kettle is always warm, and the back garden is a tangle of useful weeds.",
        tags: ["healer"]
      },
      parent: "market_square",
      sceneType: "downtime",
      cell: { x: 11, y: 1 }
    },
    chapel_quiet_bell: {
      id: "chapel_quiet_bell",
      name: "Chapel of the Quiet Bell",
      fields: {
        description: "A small, plain chapel with a square tower and a bell that no one has heard in thirty years. Candles, polished pews and a vestry off the nave smelling of beeswax and old dust.",
        tags: ["chapel"]
      },
      parent: "market_square",
      sceneType: "conversation",
      cell: { x: 2, y: 8 }
    },
    dunmore_forge: {
      id: "dunmore_forge",
      name: "Dunmore's Forge",
      fields: {
        description: "A smoky, open-fronted forge where hinges, nails, knives and ferry chain come off the anvil. A bench by the door has worn smooth under three generations of loiterers.",
        tags: ["smith"]
      },
      parent: "market_square",
      sceneType: "action",
      cell: { x: 12, y: 8 }
    },
    ferry_landing: {
      id: "ferry_landing",
      name: "Ferry Landing",
      fields: {
        description: "A gravel slip, a boathouse and a squat toll-hut at the foot of the town. A flat ferry hauled on a rope crosses the Wend to the far bank in about a quarter of an hour.",
        tags: ["waterfront"]
      },
      parent: "brindlemere",
      sceneType: "exploration"
    },
    wend_mill: {
      id: "wend_mill",
      name: "Wend Mill",
      fields: {
        description: "A three-storey mill on the river bend, its wheel as tall as a cottage. When it turns, the whole lower town hears the low thrum of the stones.",
        tags: ["mill"]
      },
      parent: "brindlemere",
      sceneType: "action"
    },
    hollin_quarry: {
      id: "hollin_quarry",
      name: "Hollin Quarry",
      fields: {
        description: "A grassed-over quarry above the old apple terraces, where the town's first millstones were cut. Rough-hewn blocks still lie in the nettles where the cutters left them.",
        tags: ["quarry"]
      },
      parent: "wend_vale",
      sceneType: "exploration"
    },
    far_bank_waystation: {
      id: "far_bank_waystation",
      name: "Far Bank Waystation",
      fields: {
        description: "A lonely stone house across the river where drovers and pilgrims wait for the ferry. A lamp burns in its window every night.",
        tags: ["waystation"]
      },
      parent: "wend_vale",
      sceneType: "conversation"
    },
    chapel_cistern: {
      id: "chapel_cistern",
      name: "Under the Chapel",
      fields: { description: "Damp stone steps lead down into a low, cold room that smells of old water and wet stone.", tags: ["hidden"] },
      parent: "chapel_quiet_bell",
      sceneType: "exploration",
      visibility: "secret"
    }
  },
