          objectives: [{ label: "Work out why Township pickup won't start", when: "flag('relay_replaced')" }],
          cue: "The township pickup turns over fine but never fires. You hear nothing from the fuel tank when you turn the key to ON.",
          answer: { expect: ["fuel pump relay", "the fuel pump relay", "bad fuel pump relay", "relay"], normalize: true },
