    id: "attack",
    label: "Attack",
    params: { target: { type: "ref", label: "Target" } },
    requires: ["is_foe(self, target)", "not is_down(target)"],
    check: "attack",
    outcomes: { critical: damage(critical), hit: damage(hit), miss: [] },
    duration: "0",
