        await this.queued(`${userId}\x00`, async () => this.sync(await this.host.regex.globalScripts(userId), ["unwrap.display", "unwrap.prompt"], { "unwrap.display": unwrapScript("display"), "unwrap.prompt": unwrapScript("prompt") }, userId));
