var DIAGNOSTICS_LOG = "diagnostics/backend.log";
var USER_DIAGNOSTICS_LOG = "diagnostics.log";
var TOKEN_COUNT_MS = 1000;

class DiagnosticsLog {
  lines = [];
  users = new Map;
  dirty = new Set;
  timer = null;
  add(level, message, userId) {
    const line = `${new Date().toISOString()} ${level} ${message}`;
    const list = userId ? this.users.get(userId) ?? [] : this.lines;
    list.push(line);
    if (list.length > 400)
      list.splice(0, list.length - 400);
    if (userId) {
      this.users.set(userId, list);
      if (this.users.size > 256)
        this.users.delete(this.users.keys().next().value ?? "");
    }
    this.dirty.add(userId ?? null);
    if (this.timer)
      return;
    this.timer = setTimeout(() => {
      this.timer = null;
      for (const who of this.dirty) {
        if (who === null)
          spindle.storage.write(DIAGNOSTICS_LOG, `${this.lines.join(`
`)}
`).catch(() => {
            return;
          });
        else
          spindle.userStorage.write(USER_DIAGNOSTICS_LOG, `${(this.users.get(who) ?? []).join(`
`)}
`, who).catch(() => {
            return;
          });
      }
      this.dirty.clear();
    }, 1000);
  }
}
async function listScripts(options, userId) {
  const out = [];
  for (let offset = 0;offset < 1e5; offset += 200) {
    const page = await spindle.regex_scripts.list({ ...options, limit: 200, offset, userId });
    for (const s of page.data) {
      const chatId = s.scope === "chat" ? s.scope_id : null;
      if (s.scope !== options.scope || s.scope === "chat" && !chatId)
        continue;
      out.push({ id: s.id, chatId, mine: s.can_mutate, findRegex: s.find_regex, replaceString: s.replace_string, flags: s.flags, placement: [...s.placement], targets: Array.isArray(s.target) ? [...s.target] : [s.target], runOnEdit: s.run_on_edit, sortOrder: s.sort_order, metadata: toJsonObject(s.metadata) });
    }
    if (page.data.length < 200 || offset + page.data.length >= page.total)
      break;
  }
  return out;
}
